def is_balanced_square(s):
    balance = 0
    for ch in s:
        if ch == '[':
            balance += 1
        elif ch == ']':
            if balance == 0:
                return False
            balance -= 1
        else:
            return False
    return balance == 0

def sort_by_product_of_digits(nums):
    def digit_product(x):
        product = 1
        for ch in str(x):
            product *= int(ch)
        return product
    return sorted(nums, key=lambda v: (digit_product(v), v))

