def matches_wildcard(s, pattern):
    s_idx = p_idx = 0
    star_idx = -1
    match_idx = 0
    while s_idx < len(s):
        if p_idx < len(pattern) and (pattern[p_idx] == '?' or pattern[p_idx] == s[s_idx]):
            s_idx += 1
            p_idx += 1
        elif p_idx < len(pattern) and pattern[p_idx] == '*':
            star_idx = p_idx
            match_idx = s_idx
            p_idx += 1
        elif star_idx != -1:
            p_idx = star_idx + 1
            match_idx += 1
            s_idx = match_idx
        else:
            return False
    return all(c == '*' for c in pattern[p_idx:])

def date_to_ordinal(date):
    y, m, d = date
    def leap(yy):
        return yy % 4 == 0 and (yy % 100 != 0 or yy % 400 == 0)
    month_days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    days = (y - 1) * 365 + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
    for i in range(m - 1):
        days += month_days[i]
    if m > 2 and leap(y):
        days += 1
    return days + d

