def sum_proper_divisors(n):
    if n <= 1:
        return 0
    divisors = []
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            j = n // i
            if j != i and j != n:
                divisors.append(j)
    return sum(divisors)
